    make(3, "半徑 8 公分、圓心角 90° 的扇形面積為何？（取 π＝3.14）", {"A": "25.12 平方公分", "B": "50.24 平方公分", "C": "100.48 平方公分", "D": "200.96 平方公分"}, "B", "90° 是整圓的四分之一，所以扇形面積為 1/4×3.14×8²＝1/4×200.96＝50.24 平方公分，選 B。", "先把圓心角換成占整圓的比例，再乘完整圓面積。", ["計算角度比例 90/360＝1/4。", "完整圓面積為 3.14×8²＝200.96。", "扇形面積是 200.96 的四分之一。", "得到 50.24 平方公分。", "確認面積小於整圓且選 B。"], "medium"),
    make(4, "半徑 9 公分、圓心角 120° 的弧長為何？（取 π＝3.14）", {"A": "6.28 公分", "B": "12.56 公分", "C": "18.84 公分", "D": "37.68 公分"}, "C", "弧長是整個圓周長的 120/360＝1/3，所以弧長＝1/3×2×3.14×9＝18.84 公分，選 C。", "弧長題先求圓周長，再乘圓心角占 360° 的比例。", ["找出角度比例 120/360＝1/3。", "求半徑 9 的圓周長 2×3.14×9＝56.52。", "取圓周長的三分之一。", "56.52÷3＝18.84 公分。", "弧長為長度且小於整圓周長，選 C。"], "medium"),
