    make(9, "半徑 10 公分的圓中，圓心角 180° 的扇形占全圓面積的幾分之幾？", {"A": "1/2", "B": "1/3", "C": "1/4", "D": "2/3"}, "A", "扇形占全圓的比例等於圓心角占 360° 的比例，180/360＝1/2，選 A。", "這題問比例，不必計算 π 或半徑；直接比較圓心角與 360°。", ["確認整圓角度是 360°。", "扇形角度為 180°。", "建立比例 180/360。", "約分為 1/2。", "所以選 A。"], "easy"),
    make(10, "圓心角相同時，兩個扇形的面積比等於其半徑比的幾次方？", {"A": "一次方", "B": "二次方", "C": "三次方", "D": "四次方"}, "B", "扇形面積為 (圓心角/360°)πr²；圓心角相同時前面的比例相同，因此面積比等於半徑平方比，選 B。", "先固定相同的圓心角，再觀察面積公式中半徑出現兩次。", ["寫出兩扇形面積公式。", "因圓心角相同，角度比例與 π 可約去。", "剩下 A₁:A₂＝r₁²:r₂²。", "因此半徑比要平方。", "答案是二次方，選 B。"], "medium"),
